const input = $input.first().json.body;

if (!input || !input.patientTelegramChatId) {
  return [{ json: { skipped: true, reason: 'No patientTelegramChatId' } }];
}

const chatId = input.patientTelegramChatId;
const prescriptionId = input.id;
const token = "8644047281:AAHywXMMM9zpDThyBj_FOgme46RZi_GhzRk";

let pharmacies = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://localhost:8081/api/pharmacies',
    headers: { 'Content-Type': 'application/json' }
  });
  pharmacies = Array.isArray(resp) ? resp : (resp.data || resp.results || []);
} catch(e) {}

const keyboard = [];
let row = [];
for (const pharm of pharmacies) {
  row.push({
    text: pharm.pharmacyName,
    callback_data: 'pick:' + prescriptionId + ':' + pharm.id
  });
  if (row.length === 2) {
    keyboard.push(row);
    row = [];
  }
}
if (row.length > 0) keyboard.push(row);

const text = '\uD83C\uDFE5 *Nouvelle ordonnance médicale* \u2013 N\u00B0 ' + prescriptionId + '\n\nBonjour,\n\nUne ordonnance électronique vient d\u2019\u00EAtre établie à votre nom par votre médecin traitant.\n\nVeuillez sélectionner la pharmacie de votre choix ci-dessous pour sa préparation :';

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + token + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: {
    chat_id: chatId,
    text: text,
    parse_mode: 'Markdown',
    reply_markup: { inline_keyboard: keyboard }
  }
});

return [{ json: { success: true, chatId, prescriptionId, messageId: response.result.message_id, pharmacyCount: pharmacies.length, keyboardRows: keyboard.length } }];
